select '27a27620-fb14-5129-bd9f-2207664bd030', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Derechos fundamentales","text":"La Constitución de 1991 incluye un capítulo de derechos fundamentales, como la vida, la igualdad, la libertad de expresión, el debido proceso y el derecho de petición. También reconoce derechos sociales, económicos y culturales, como la salud, la educación y la vivienda digna, y derechos colectivos y del ambiente.","svg":null,"table":null}'::jsonb, '¿Cuál de estos es un derecho colectivo?', '[{"label":"A","text":"El derecho de petición.","is_correct":false,"distractor_type":"Confunde un derecho individual con uno colectivo.","explanation_feedback":"Incorrecta. Cada persona ejerce el derecho de petición."},{"label":"B","text":"El derecho al debido proceso.","is_correct":false,"distractor_type":"Confunde un derecho individual con uno colectivo.","explanation_feedback":"Incorrecta. El debido proceso protege a cada persona en un trámite o juicio."},{"label":"C","text":"El derecho a la libertad de expresión.","is_correct":false,"distractor_type":"Confunde un derecho individual con uno colectivo.","explanation_feedback":"Incorrecta. La libertad de expresión es un derecho fundamental de cada persona."},{"label":"D","text":"El derecho a gozar de un ambiente sano.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El ambiente sano pertenece a toda la comunidad: es un derecho colectivo."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'SC.E1.1'
on conflict (id) do nothing;
