select '55fd62e3-0171-529a-b92d-772cbe2bdc4f', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Derechos fundamentales","text":"La Constitución de 1991 incluye un capítulo de derechos fundamentales, como la vida, la igualdad, la libertad de expresión, el debido proceso y el derecho de petición. También reconoce derechos sociales, económicos y culturales, como la salud, la educación y la vivienda digna, y derechos colectivos y del ambiente.","svg":null,"table":null}'::jsonb, 'Un periodista es amenazado por publicar una investigación. ¿Qué derecho fundamental está en riesgo?', '[{"label":"A","text":"El derecho al ambiente sano.","is_correct":false,"distractor_type":"Elige un derecho colectivo sin relación.","explanation_feedback":"Incorrecta. La amenaza no se relaciona con el ambiente."},{"label":"B","text":"El derecho a la propiedad intelectual.","is_correct":false,"distractor_type":"Confunde la publicación con derechos de autor.","explanation_feedback":"Incorrecta. El problema es la amenaza por informar."},{"label":"C","text":"La libertad de expresión e información.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Amenazar a un periodista por lo que publica busca silenciarlo."},{"label":"D","text":"El derecho a la vivienda digna.","is_correct":false,"distractor_type":"Elige un derecho social sin relación.","explanation_feedback":"Incorrecta. La amenaza no tiene que ver con la vivienda."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E1.4'
