select 'bdb21ab2-16e9-586d-81fb-50bd6120c3a0', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Elecciones en Colombia","text":"En Colombia se eligen por voto popular el presidente, los congresistas, los gobernadores, los diputados, los alcaldes, los concejales y los ediles. El presidente y los congresistas se eligen cada cuatro años, al igual que las autoridades departamentales y municipales, en elecciones separadas.","svg":null,"table":null}'::jsonb, '¿Quién gobierna un departamento?', '[{"label":"A","text":"El senador.","is_correct":false,"distractor_type":"Confunde ramas del poder.","explanation_feedback":"Incorrecta. Los senadores hacen parte del Congreso."},{"label":"B","text":"El alcalde.","is_correct":false,"distractor_type":"Confunde niveles territoriales.","explanation_feedback":"Incorrecta. El alcalde gobierna el municipio."},{"label":"C","text":"El gobernador.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El gobernador es la máxima autoridad ejecutiva del departamento."},{"label":"D","text":"El edil.","is_correct":false,"distractor_type":"Confunde niveles territoriales.","explanation_feedback":"Incorrecta. Los ediles hacen parte de las juntas administradoras locales."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
