select 'a76bff5a-d0f8-5705-ac35-817f01c48644', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Elecciones en Colombia","text":"En Colombia se eligen por voto popular el presidente, los congresistas, los gobernadores, los diputados, los alcaldes, los concejales y los ediles. El presidente y los congresistas se eligen cada cuatro años, al igual que las autoridades departamentales y municipales, en elecciones separadas.","svg":null,"table":null}'::jsonb, '¿Qué corporación aprueba los acuerdos que rigen en un municipio?', '[{"label":"A","text":"La asamblea departamental.","is_correct":false,"distractor_type":"Confunde niveles territoriales.","explanation_feedback":"Incorrecta. La asamblea expide ordenanzas para el departamento."},{"label":"B","text":"El concejo municipal.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los concejales aprueban acuerdos municipales, como el presupuesto o el plan de desarrollo."},{"label":"C","text":"La Cámara de Representantes.","is_correct":false,"distractor_type":"Confunde niveles territoriales.","explanation_feedback":"Incorrecta. La Cámara hace parte del Congreso, que hace leyes."},{"label":"D","text":"La Corte Suprema de Justicia.","is_correct":false,"distractor_type":"Confunde ramas.","explanation_feedback":"Incorrecta. La Corte Suprema es un tribunal."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
