insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '92b26a9f-bf97-5194-bcc8-d5a7f3c450a3', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Elecciones en Colombia","text":"En Colombia se eligen por voto popular el presidente, los congresistas, los gobernadores, los diputados, los alcaldes, los concejales y los ediles. El presidente y los congresistas se eligen cada cuatro años, al igual que las autoridades departamentales y municipales, en elecciones separadas.","svg":null,"table":null}'::jsonb, '¿Cuál es la relación correcta entre corporación y tipo de norma?', '[{"label":"A","text":"Congreso: acuerdos; asamblea: leyes; concejo: ordenanzas.","is_correct":false,"distractor_type":"Mezcla los tipos de norma.","explanation_feedback":"Incorrecta. El Congreso expide leyes, no acuerdos."},{"label":"B","text":"Congreso: leyes; asamblea departamental: ordenanzas; concejo: acuerdos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Cada corporación expide su tipo de norma en su nivel territorial."},{"label":"C","text":"Congreso: ordenanzas; asamblea: acuerdos; concejo: leyes.","is_correct":false,"distractor_type":"Mezcla los tipos de norma.","explanation_feedback":"Incorrecta. Los concejos expiden acuerdos."},{"label":"D","text":"Las tres corporaciones expiden solo leyes.","is_correct":false,"distractor_type":"Ignora la diferencia de niveles.","explanation_feedback":"Incorrecta. Solo el Congreso expide leyes."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'SC.E1.3'
on conflict (id) do nothing;
