select '37afbc2c-d5f2-590f-9096-2799ecfc2691', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La economía de un hogar","text":"La familia Díaz recibe 2.500.000 pesos al mes. Gasta 900.000 en arriendo, 800.000 en alimentación, 300.000 en transporte, 200.000 en servicios públicos y ahorra el resto. Este año los precios de los alimentos subieron un 10 %, pero sus ingresos no aumentaron.","svg":null,"table":null}'::jsonb, '¿Cuánto ahorra la familia Díaz al mes antes del aumento de precios?', '[{"label":"A","text":"800.000 pesos.","is_correct":false,"distractor_type":"Confunde el ahorro con el gasto en alimentación.","explanation_feedback":"Incorrecta. 800.000 es el gasto en comida."},{"label":"B","text":"500.000 pesos.","is_correct":false,"distractor_type":"Olvida sumar un gasto.","explanation_feedback":"Incorrecta. Hay que restar los cuatro gastos."},{"label":"C","text":"200.000 pesos.","is_correct":false,"distractor_type":"Confunde el ahorro con el gasto en servicios.","explanation_feedback":"Incorrecta. Los servicios cuestan 200.000; el ahorro es lo que sobra."},{"label":"D","text":"300.000 pesos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. 2.500.000 − (900.000 + 800.000 + 300.000 + 200.000) = 300.000."}]'::jsonb, null, 0.9, -1.2, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'SC.E1.1'
on conflict (id) do nothing;
