select '64cf06dc-263b-5849-bebe-908828589005', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La economía de un hogar","text":"La familia Díaz recibe 2.500.000 pesos al mes. Gasta 900.000 en arriendo, 800.000 en alimentación, 300.000 en transporte, 200.000 en servicios públicos y ahorra el resto. Este año los precios de los alimentos subieron un 10 %, pero sus ingresos no aumentaron.","svg":null,"table":null}'::jsonb, 'Si la familia sigue comprando los mismos alimentos, ¿qué pasa con su ahorro?', '[{"label":"A","text":"Desaparece, porque el 10 % es todo el ahorro.","is_correct":false,"distractor_type":"Calcula mal el 10 %.","explanation_feedback":"Incorrecta. El aumento es de 80.000, no de 300.000."},{"label":"B","text":"Sube, porque los precios aumentaron.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. Si los precios suben y el ingreso no, el ahorro baja."},{"label":"C","text":"Se mantiene igual, porque el ingreso no cambió.","is_correct":false,"distractor_type":"Ignora el aumento del gasto.","explanation_feedback":"Incorrecta. El gasto en comida aumenta."},{"label":"D","text":"Baja a 220.000 pesos, porque la comida cuesta 80.000 pesos más.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El 10 % de 800.000 es 80.000; el ahorro pasa de 300.000 a 220.000."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E1.1'
on conflict (id) do nothing;
