select 'ffacff50-9ae7-546e-a877-f3ce4ce3a8e0', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La economía de un hogar","text":"La familia Díaz recibe 2.500.000 pesos al mes. Gasta 900.000 en arriendo, 800.000 en alimentación, 300.000 en transporte, 200.000 en servicios públicos y ahorra el resto. Este año los precios de los alimentos subieron un 10 %, pero sus ingresos no aumentaron.","svg":null,"table":null}'::jsonb, '¿Qué concepto describe el aumento de precios con ingresos constantes?', '[{"label":"A","text":"Superávit del hogar.","is_correct":false,"distractor_type":"Confunde con tener más ingresos que gastos.","explanation_feedback":"Incorrecta. El ahorro de la familia disminuye."},{"label":"B","text":"Deflación general.","is_correct":false,"distractor_type":"Confunde con la caída de precios.","explanation_feedback":"Incorrecta. La deflación es una baja general de precios."},{"label":"C","text":"Pérdida de poder adquisitivo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Con el mismo dinero se pueden comprar menos bienes."},{"label":"D","text":"Aumento del salario real.","is_correct":false,"distractor_type":"Invierte el concepto.","explanation_feedback":"Incorrecta. El salario real baja cuando suben los precios y el ingreso no."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
