select '35180130-63df-553e-9a52-a67b9538fb7a', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La Conquista y el mestizaje","text":"Tras la llegada de los españoles en el siglo XVI, la población indígena del territorio que hoy es Colombia disminuyó drásticamente por las guerras, el trabajo forzado y enfermedades como la viruela. Los españoles trajeron personas africanas esclavizadas para trabajar en minas y haciendas. De la mezcla entre indígenas, africanos y europeos surgió una sociedad diversa, pero organizada en jerarquías según el origen.","svg":null,"table":null}'::jsonb, '¿En qué siglo comenzó la Conquista española en el territorio colombiano?', '[{"label":"A","text":"En el siglo XX.","is_correct":false,"distractor_type":"Confunde siglos.","explanation_feedback":"Incorrecta. El siglo XX es el de 1900."},{"label":"B","text":"En el siglo XIII.","is_correct":false,"distractor_type":"Confunde siglos.","explanation_feedback":"Incorrecta. En el siglo XIII aún no habían llegado los europeos."},{"label":"C","text":"En el siglo XIX.","is_correct":false,"distractor_type":"Confunde con la independencia.","explanation_feedback":"Incorrecta. En el siglo XIX ocurrió la independencia."},{"label":"D","text":"En el siglo XVI.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto dice que los españoles llegaron en el siglo XVI (años 1500)."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'SC.E2.1'
on conflict (id) do nothing;
