select 'ed2b5a1e-39ff-56e9-a05e-5d92ac4b6c8b', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La Conquista y el mestizaje","text":"Tras la llegada de los españoles en el siglo XVI, la población indígena del territorio que hoy es Colombia disminuyó drásticamente por las guerras, el trabajo forzado y enfermedades como la viruela. Los españoles trajeron personas africanas esclavizadas para trabajar en minas y haciendas. De la mezcla entre indígenas, africanos y europeos surgió una sociedad diversa, pero organizada en jerarquías según el origen.","svg":null,"table":null}'::jsonb, '¿Por qué los españoles trajeron personas africanas esclavizadas?', '[{"label":"A","text":"Para reemplazar mano de obra en minas y haciendas tras la caída de la población indígena.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La disminución de la población indígena llevó a buscar trabajadores forzados en África."},{"label":"B","text":"Para fundar colegios en las ciudades.","is_correct":false,"distractor_type":"Inventa una razón.","explanation_feedback":"Incorrecta. El texto habla de minas y haciendas."},{"label":"C","text":"Porque los africanos lo pidieron voluntariamente.","is_correct":false,"distractor_type":"Contradice la idea de esclavitud.","explanation_feedback":"Incorrecta. Eran personas esclavizadas, no voluntarias."},{"label":"D","text":"Para enseñar a los indígenas a cultivar.","is_correct":false,"distractor_type":"Inventa una razón.","explanation_feedback":"Incorrecta. El texto habla de trabajo en minas y haciendas."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E2.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '36bb03da-b590-5d60-93e6-8e7f39bfa1a2', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La Conquista y el mestizaje","text":"Tras la llegada de los españoles en el siglo XVI, la población indígena del territorio que hoy es Colombia disminuyó drásticamente por las guerras, el trabajo forzado y enfermedades como la viruela. Los españoles trajeron personas africanas esclavizadas para trabajar en minas y haciendas. De la mezcla entre indígenas, africanos y europeos surgió una sociedad diversa, pero organizada en jerarquías según el origen.","svg":null,"table":null}'::jsonb, '¿Qué consecuencia de largo plazo tuvo la organización en jerarquías según el origen?', '[{"label":"A","text":"La desaparición de toda diferencia social desde 1810.","is_correct":false,"distractor_type":"Supone un cambio inmediato.","explanation_feedback":"Incorrecta. La independencia no eliminó de inmediato las desigualdades."},{"label":"B","text":"Desigualdades sociales que persistieron después de la independencia.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las jerarquías coloniales dejaron desigualdades que tardaron mucho en transformarse."},{"label":"C","text":"Que no hubiera mestizaje en Colombia.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. El texto dice que hubo mezcla."},{"label":"D","text":"Que todos los grupos tuvieran los mismos derechos en la Colonia.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. El texto habla de jerarquías."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'c1a8b672-09fb-5cb9-85d3-147705b00f50', e.id, 'SC', null, 'qa_passed', 'discontinuous', '{"title":"Clima y cultivos","text":null,"svg":null,"table":{"caption":"Pisos térmicos de Colombia y algunos cultivos típicos (valores aproximados)","headers":["Piso térmico","Altura (metros)","Temperatura promedio","Cultivos típicos"],"rows":[["Cálido","0 - 1.000","más de 24 °C","Plátano, cacao, arroz"],["Templado","1.000 - 2.000","17 - 24 °C","Café, caña panelera"],["Frío","2.000 - 3.000","12 - 17 °C","Papa, trigo"],["Páramo","más de 3.000","menos de 12 °C","Pocos cultivos; reserva de agua"]]}}'::jsonb, '¿En qué piso térmico se cultiva típicamente el café?', '[{"label":"A","text":"Templado.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La tabla ubica el café en el piso templado, entre 1.000 y 2.000 metros."},{"label":"B","text":"Páramo.","is_correct":false,"distractor_type":"Confunde pisos térmicos.","explanation_feedback":"Incorrecta. El páramo tiene pocos cultivos."},{"label":"C","text":"Frío.","is_correct":false,"distractor_type":"Confunde pisos térmicos.","explanation_feedback":"Incorrecta. En el frío están la papa y el trigo."},{"label":"D","text":"Cálido.","is_correct":false,"distractor_type":"Confunde pisos térmicos.","explanation_feedback":"Incorrecta. En el cálido están el plátano, el cacao y el arroz."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
