select '7f3c89ed-656a-562b-8ff8-e3dc4a739564', e.id, 'SC', null, 'qa_passed', 'discontinuous', '{"title":"Clima y cultivos","text":null,"svg":null,"table":{"caption":"Pisos térmicos de Colombia y algunos cultivos típicos (valores aproximados)","headers":["Piso térmico","Altura (metros)","Temperatura promedio","Cultivos típicos"],"rows":[["Cálido","0 - 1.000","más de 24 °C","Plátano, cacao, arroz"],["Templado","1.000 - 2.000","17 - 24 °C","Café, caña panelera"],["Frío","2.000 - 3.000","12 - 17 °C","Papa, trigo"],["Páramo","más de 3.000","menos de 12 °C","Pocos cultivos; reserva de agua"]]}}'::jsonb, 'Un municipio está a 2.600 metros de altura. Según la tabla, ¿qué producción agrícola es más probable allí?', '[{"label":"A","text":"Café.","is_correct":false,"distractor_type":"Ubica el municipio en el piso templado.","explanation_feedback":"Incorrecta. El café es del piso templado, entre 1.000 y 2.000 m."},{"label":"B","text":"Papa.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. 2.600 m está en el piso frío, donde se cultiva papa."},{"label":"C","text":"Cacao.","is_correct":false,"distractor_type":"Ubica el municipio en el piso cálido.","explanation_feedback":"Incorrecta. El cacao es del piso cálido, por debajo de 1.000 m."},{"label":"D","text":"Arroz.","is_correct":false,"distractor_type":"Ubica el municipio en el piso cálido.","explanation_feedback":"Incorrecta. El arroz es del piso cálido."}]'::jsonb, null, 1.1, 0, 0.25, 45, 'original_generated'
