select '4f08d88d-0095-586a-8006-9682792e532b', e.id, 'SC', null, 'qa_passed', 'discontinuous', '{"title":"Clima y cultivos","text":null,"svg":null,"table":{"caption":"Pisos térmicos de Colombia y algunos cultivos típicos (valores aproximados)","headers":["Piso térmico","Altura (metros)","Temperatura promedio","Cultivos típicos"],"rows":[["Cálido","0 - 1.000","más de 24 °C","Plátano, cacao, arroz"],["Templado","1.000 - 2.000","17 - 24 °C","Café, caña panelera"],["Frío","2.000 - 3.000","12 - 17 °C","Papa, trigo"],["Páramo","más de 3.000","menos de 12 °C","Pocos cultivos; reserva de agua"]]}}'::jsonb, 'Si la frontera agrícola de la papa sube hacia el páramo, ¿qué efecto es más probable?', '[{"label":"A","text":"Aumenta la producción de café en el piso templado.","is_correct":false,"distractor_type":"Inventa una relación.","explanation_feedback":"Incorrecta. Cultivar papa en el páramo no aumenta el café."},{"label":"B","text":"El páramo se vuelve piso cálido.","is_correct":false,"distractor_type":"Confunde uso del suelo con clima.","explanation_feedback":"Incorrecta. El cultivo no cambia la altura ni el piso térmico."},{"label":"C","text":"Mejora la reserva de agua del páramo.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. Cultivar el páramo deteriora su función hídrica."},{"label":"D","text":"Se afecta la regulación del agua que el páramo provee a zonas más bajas.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La tabla describe el páramo como reserva de agua; cultivarlo la pone en riesgo."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
