select 'ab3b2068-8a10-5287-ac6e-41feeb470eeb', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La independencia","text":"El 20 de julio de 1810, en Santa Fe, criollos y otros sectores de la población formaron una Junta de Gobierno. En los años siguientes, las provincias discutieron si debían organizarse como un Estado central o como una federación, y se enfrentaron entre sí en la llamada «Patria Boba». En 1816 las tropas españolas reconquistaron el territorio, y la independencia se consolidó tras la Batalla de Boyacá, en 1819.","svg":null,"table":null}'::jsonb, '¿Qué periodo transcurrió entre la formación de la Junta de Gobierno y la reconquista española?', '[{"label":"A","text":"La llamada Patria Boba, con guerras entre provincias.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Entre 1810 y 1816 las provincias se enfrentaron por el modelo de Estado."},{"label":"B","text":"La Regeneración de 1886.","is_correct":false,"distractor_type":"Confunde periodos.","explanation_feedback":"Incorrecta. La Regeneración fue a finales del siglo XIX."},{"label":"C","text":"La Conquista española.","is_correct":false,"distractor_type":"Confunde periodos.","explanation_feedback":"Incorrecta. La Conquista fue en el siglo XVI."},{"label":"D","text":"El Frente Nacional del siglo XX.","is_correct":false,"distractor_type":"Confunde periodos.","explanation_feedback":"Incorrecta. El Frente Nacional fue entre 1958 y 1974."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
