select '75da9376-8f40-5d6a-ba7a-c62457dc9951', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La independencia","text":"El 20 de julio de 1810, en Santa Fe, criollos y otros sectores de la población formaron una Junta de Gobierno. En los años siguientes, las provincias discutieron si debían organizarse como un Estado central o como una federación, y se enfrentaron entre sí en la llamada «Patria Boba». En 1816 las tropas españolas reconquistaron el territorio, y la independencia se consolidó tras la Batalla de Boyacá, en 1819.","svg":null,"table":null}'::jsonb, '¿Qué relación tiene la «Patria Boba» con la reconquista española de 1816?', '[{"label":"A","text":"España apoyó a los federalistas para ganar.","is_correct":false,"distractor_type":"Inventa un hecho.","explanation_feedback":"Incorrecta. El texto no dice eso."},{"label":"B","text":"Las divisiones internas debilitaron a los independentistas frente a las tropas españolas.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los enfrentamientos entre provincias facilitaron la reconquista."},{"label":"C","text":"La reconquista ocurrió porque todos estaban unidos.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. El texto describe enfrentamientos internos."},{"label":"D","text":"La Patria Boba ocurrió después de la Batalla de Boyacá.","is_correct":false,"distractor_type":"Desordena los hechos.","explanation_feedback":"Incorrecta. La Patria Boba fue antes de 1816."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
