select '1d09163a-1794-5e45-b71a-d2c708a1fa4e', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Un acuerdo de convivencia","text":"En un colegio, los estudiantes de grado 10 y 11 discuten por el uso de la cancha en los descansos. El consejo estudiantil propone tres opciones: (1) turnos por días para cada grado; (2) que la use quien llegue primero; (3) que el rector decida sin consultar.","svg":null,"table":null}'::jsonb, '¿Qué opción tiene en cuenta a los dos grados de manera equitativa?', '[{"label":"A","text":"Los turnos por días para cada grado.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los turnos garantizan que ambos grados usen la cancha."},{"label":"B","text":"Que la use quien llegue primero.","is_correct":false,"distractor_type":"Ignora que puede favorecer siempre a los mismos.","explanation_feedback":"Incorrecta. Quien llegue primero podría ser siempre el mismo grupo."},{"label":"C","text":"Que nadie use la cancha.","is_correct":false,"distractor_type":"Evita el conflicto sin resolverlo.","explanation_feedback":"Incorrecta. Ninguno de los grados se beneficia."},{"label":"D","text":"Que el rector decida sin consultar.","is_correct":false,"distractor_type":"Excluye la participación.","explanation_feedback":"Incorrecta. No tiene en cuenta las perspectivas de los estudiantes."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
