select 'e95b9d23-fc26-5823-894f-c7c14eaee544', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Un acuerdo de convivencia","text":"En un colegio, los estudiantes de grado 10 y 11 discuten por el uso de la cancha en los descansos. El consejo estudiantil propone tres opciones: (1) turnos por días para cada grado; (2) que la use quien llegue primero; (3) que el rector decida sin consultar.","svg":null,"table":null}'::jsonb, '¿Qué órgano del gobierno escolar presentó la propuesta?', '[{"label":"A","text":"El Congreso de la República.","is_correct":false,"distractor_type":"Confunde niveles.","explanation_feedback":"Incorrecta. El Congreso es nacional, no escolar."},{"label":"B","text":"El concejo municipal.","is_correct":false,"distractor_type":"Confunde niveles.","explanation_feedback":"Incorrecta. El concejo es del municipio."},{"label":"C","text":"La Registraduría Nacional.","is_correct":false,"distractor_type":"Confunde instituciones.","explanation_feedback":"Incorrecta. La Registraduría organiza elecciones nacionales."},{"label":"D","text":"El consejo estudiantil.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El consejo estudiantil asegura la participación de los estudiantes en el gobierno escolar."}]'::jsonb, null, 1.1, 0, 0.25, 45, 'original_generated'
