select '91aba51b-af45-5326-8dbe-92bc3220032d', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Ventas ambulantes","text":"Una alcaldía decide retirar a los vendedores ambulantes de las aceras del centro para recuperar el espacio público. Los vendedores dicen que es su único sustento. Los peatones se quejan de que no pueden caminar. La Corte Constitucional ha dicho que las autoridades pueden recuperar el espacio público, pero deben ofrecer alternativas a quienes dependen de esa actividad.","svg":null,"table":null}'::jsonb, '¿De qué se quejan los peatones?', '[{"label":"A","text":"De que no hay buses en el centro.","is_correct":false,"distractor_type":"Inventa una queja.","explanation_feedback":"Incorrecta. El texto no habla de buses."},{"label":"B","text":"De que la Corte no los escuchó.","is_correct":false,"distractor_type":"Inventa una queja.","explanation_feedback":"Incorrecta. El texto no dice eso."},{"label":"C","text":"De que no pueden caminar por las aceras.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Es lo que dice el texto."},{"label":"D","text":"De que perdieron su único sustento.","is_correct":false,"distractor_type":"Les atribuye el argumento de los vendedores.","explanation_feedback":"Incorrecta. Eso lo dicen los vendedores."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
