select '9a4f4b1e-d60a-54b3-bdb7-08548aba1c47', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Ventas ambulantes","text":"Una alcaldía decide retirar a los vendedores ambulantes de las aceras del centro para recuperar el espacio público. Los vendedores dicen que es su único sustento. Los peatones se quejan de que no pueden caminar. La Corte Constitucional ha dicho que las autoridades pueden recuperar el espacio público, pero deben ofrecer alternativas a quienes dependen de esa actividad.","svg":null,"table":null}'::jsonb, '¿Qué solución es coherente con lo dicho por la Corte Constitucional?', '[{"label":"A","text":"Multar a los peatones que se quejen.","is_correct":false,"distractor_type":"Propone una medida sin sentido.","explanation_feedback":"Incorrecta. Los peatones no causan el problema."},{"label":"B","text":"Dejar las aceras ocupadas sin ninguna regulación.","is_correct":false,"distractor_type":"Ignora a los peatones.","explanation_feedback":"Incorrecta. La Corte reconoce que se puede recuperar el espacio público."},{"label":"C","text":"Recuperar las aceras y reubicar a los vendedores en espacios adecuados con apoyo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La Corte permite recuperar el espacio público si se ofrecen alternativas."},{"label":"D","text":"Retirar a los vendedores sin ofrecer ninguna alternativa.","is_correct":false,"distractor_type":"Ignora la condición de la Corte.","explanation_feedback":"Incorrecta. La Corte exige alternativas."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
