select 'd31f0455-e002-5178-8311-3bdd1939f226', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Ventas ambulantes","text":"Una alcaldía decide retirar a los vendedores ambulantes de las aceras del centro para recuperar el espacio público. Los vendedores dicen que es su único sustento. Los peatones se quejan de que no pueden caminar. La Corte Constitucional ha dicho que las autoridades pueden recuperar el espacio público, pero deben ofrecer alternativas a quienes dependen de esa actividad.","svg":null,"table":null}'::jsonb, '¿Qué tensión entre derechos muestra este caso?', '[{"label":"A","text":"El derecho colectivo al espacio público frente al derecho al trabajo de los vendedores.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La Corte busca equilibrar ambos derechos."},{"label":"B","text":"El derecho al voto frente al derecho a la salud.","is_correct":false,"distractor_type":"Elige derechos no relacionados.","explanation_feedback":"Incorrecta. El caso no trata de elecciones ni de salud."},{"label":"C","text":"La libertad religiosa frente a la propiedad.","is_correct":false,"distractor_type":"Elige derechos no relacionados.","explanation_feedback":"Incorrecta. El caso no trata de religión."},{"label":"D","text":"No hay ninguna tensión entre derechos.","is_correct":false,"distractor_type":"Ignora el conflicto.","explanation_feedback":"Incorrecta. Hay intereses legítimos enfrentados."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
