select '5ba796c1-252c-5c06-b8c7-168d53697780', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Una canción como fuente","text":"Un profesor de historia lleva a clase una canción vallenata de los años setenta que habla de la bonanza marimbera en La Guajira: el dinero fácil, las fiestas y la violencia que llegó con el tráfico de marihuana.","svg":null,"table":null}'::jsonb, '¿Para qué sirve esta canción en una clase de historia?', '[{"label":"A","text":"Para conocer cómo se vivió y se narró en la región un fenómeno económico y social.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las canciones muestran percepciones y experiencias de una época."},{"label":"B","text":"Para nada, porque las canciones no son fuentes.","is_correct":false,"distractor_type":"Descalifica la fuente.","explanation_feedback":"Incorrecta. Las canciones sí son fuentes para la historia cultural."},{"label":"C","text":"Para reemplazar todas las demás fuentes sobre el tema.","is_correct":false,"distractor_type":"Sobrevalora la fuente.","explanation_feedback":"Incorrecta. Debe complementarse con otras fuentes."},{"label":"D","text":"Para conocer cifras exactas de la producción de marihuana.","is_correct":false,"distractor_type":"Exige a la fuente algo que no da.","explanation_feedback":"Incorrecta. Una canción no da cifras confiables."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.1'
on conflict (id) do nothing;
