select 'cc816631-390c-54f4-bf79-541dc07452a6', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Una canción como fuente","text":"Un profesor de historia lleva a clase una canción vallenata de los años setenta que habla de la bonanza marimbera en La Guajira: el dinero fácil, las fiestas y la violencia que llegó con el tráfico de marihuana.","svg":null,"table":null}'::jsonb, '¿Qué precaución debe tener el profesor al usar la canción?', '[{"label":"A","text":"Recordar que expresa la mirada del compositor y contrastarla con otras fuentes.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Toda fuente tiene una perspectiva; contrastarla evita conclusiones parciales."},{"label":"B","text":"Presentarla como un informe oficial del Gobierno.","is_correct":false,"distractor_type":"Confunde el tipo de fuente.","explanation_feedback":"Incorrecta. Una canción no es un informe oficial."},{"label":"C","text":"Usarla solo si fue un éxito comercial.","is_correct":false,"distractor_type":"Confunde popularidad con valor histórico.","explanation_feedback":"Incorrecta. Su valor no depende de las ventas."},{"label":"D","text":"Cambiar la letra para que sea más precisa.","is_correct":false,"distractor_type":"Altera la fuente.","explanation_feedback":"Incorrecta. Modificar una fuente la invalida."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
