select '1dce9e4b-4de5-5075-a620-80a53a387e94', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Un plan de desarrollo","text":"Un municipio tiene un presupuesto limitado y debe elegir entre tres proyectos: pavimentar la vía principal, construir un centro de salud en la zona rural o ampliar el acueducto para que llegue a veredas que hoy toman agua del río.","svg":null,"table":null}'::jsonb, '¿Qué información sería más útil para decidir entre los proyectos?', '[{"label":"A","text":"Qué proyecto tiene el nombre más llamativo.","is_correct":false,"distractor_type":"Elige un criterio irrelevante.","explanation_feedback":"Incorrecta. El nombre no indica su impacto."},{"label":"B","text":"Cuántas personas se beneficiarían y qué necesidades básicas atiende cada uno.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Comparar beneficiarios y necesidades ayuda a priorizar con un presupuesto limitado."},{"label":"C","text":"Cuál proyecto se ve más desde la plaza principal.","is_correct":false,"distractor_type":"Elige un criterio de visibilidad.","explanation_feedback":"Incorrecta. La visibilidad no mide el beneficio."},{"label":"D","text":"Qué proyecto prefiere el contratista más grande.","is_correct":false,"distractor_type":"Elige un criterio interesado.","explanation_feedback":"Incorrecta. El interés del contratista no es un criterio de bienestar."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E6.1'
