select '31262c2c-6afb-5f19-bae0-0514a7da2f89', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Un plan de desarrollo","text":"Un municipio tiene un presupuesto limitado y debe elegir entre tres proyectos: pavimentar la vía principal, construir un centro de salud en la zona rural o ampliar el acueducto para que llegue a veredas que hoy toman agua del río.","svg":null,"table":null}'::jsonb, 'Si se amplía el acueducto, ¿qué efecto indirecto podría tener sobre el sistema de salud?', '[{"label":"A","text":"Que el centro de salud cierre de inmediato.","is_correct":false,"distractor_type":"Exagera el efecto.","explanation_feedback":"Incorrecta. Menos casos no implican cerrar el centro."},{"label":"B","text":"Menos enfermedades por agua contaminada y menos consultas por esa causa.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El agua potable reduce enfermedades como la diarrea."},{"label":"C","text":"Ningún efecto, porque agua y salud no se relacionan.","is_correct":false,"distractor_type":"Ignora la relación.","explanation_feedback":"Incorrecta. El agua segura es clave para la salud."},{"label":"D","text":"Más enfermedades por tener agua potable.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. El agua potable reduce enfermedades."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
