select '574c04c3-c328-5a0e-a4d1-6c4adc8148f5', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Inmigración reciente","text":"En los últimos años llegaron a Colombia casi tres millones de personas desde Venezuela. Algunos estudios señalan que muchos migrantes trabajan en la economía informal y que su llegada aumentó la demanda de servicios de salud y educación en ciudades fronterizas. Otros estudios indican que, a mediano plazo, la migración puede aumentar la producción y el consumo.","svg":null,"table":null}'::jsonb, '¿Qué dimensiones del fenómeno migratorio se mencionan en el texto?', '[{"label":"A","text":"Solo la cultural, por las costumbres.","is_correct":false,"distractor_type":"Elige una dimensión no tratada.","explanation_feedback":"Incorrecta. El texto no habla de costumbres."},{"label":"B","text":"Solo la militar, por la frontera.","is_correct":false,"distractor_type":"Elige una dimensión no tratada.","explanation_feedback":"Incorrecta. El texto no habla de lo militar."},{"label":"C","text":"La laboral, la de servicios sociales y la económica.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto habla de trabajo informal, demanda de salud y educación, y producción."},{"label":"D","text":"Solo la deportiva, por los torneos.","is_correct":false,"distractor_type":"Elige una dimensión no tratada.","explanation_feedback":"Incorrecta. El texto no la menciona."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'SC.E6.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '8be7ff75-2134-5a37-9455-69d8473bcaab', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Inmigración reciente","text":"En los últimos años llegaron a Colombia casi tres millones de personas desde Venezuela. Algunos estudios señalan que muchos migrantes trabajan en la economía informal y que su llegada aumentó la demanda de servicios de salud y educación en ciudades fronterizas. Otros estudios indican que, a mediano plazo, la migración puede aumentar la producción y el consumo.","svg":null,"table":null}'::jsonb, '¿Por qué el texto presenta resultados de distintos estudios?', '[{"label":"A","text":"Porque los efectos de la migración dependen del plazo y del aspecto que se analice.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. A corto plazo aumenta la demanda de servicios; a mediano plazo puede aumentar la producción."},{"label":"B","text":"Porque todos los estudios dicen exactamente lo mismo.","is_correct":false,"distractor_type":"Ignora los matices.","explanation_feedback":"Incorrecta. Los estudios destacan efectos distintos."},{"label":"C","text":"Porque solo uno de los estudios es verdadero.","is_correct":false,"distractor_type":"Supone que perspectivas distintas se excluyen.","explanation_feedback":"Incorrecta. Pueden ser complementarios."},{"label":"D","text":"Porque los estudios no hablan de migración.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Todos tratan de la migración."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
